package kz.zeroops.agent;
import java.io.*; import java.util.*; import java.util.concurrent.TimeUnit; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
/** Explicit opt-in. No shell or user-supplied command is executed. */
@Component @ConditionalOnProperty(name="agent.execution-mode",havingValue="docker") class DockerDeploymentExecutor implements DeploymentExecutor { public ExecutionResult execute(AgentBoundary.Manifest m){String name="autodeploy-"+m.projectId()+"-"+m.deploymentId();List<String> c=List.of("docker","run","--detach","--rm","--name",name,"--label","io.autodeploy.managed=true","--read-only","--cap-drop","ALL","--security-opt","no-new-privileges","--pids-limit","256","--memory","512m","--cpus","1.0","--publish","127.0.0.1::"+m.applicationPort(),m.imageTag());try{Process p=new ProcessBuilder(c).redirectErrorStream(true).start();if(!p.waitFor(45,TimeUnit.SECONDS)){p.destroyForcibly();return new ExecutionResult(false,"Docker start timed out.","Docker start timeout");}return p.exitValue()==0?new ExecutionResult(true,"Isolated Docker container started.",null):new ExecutionResult(false,"Docker rejected verified deployment.","Docker exit "+p.exitValue());}catch(IOException e){return new ExecutionResult(false,"Docker unavailable to Agent.","Docker unavailable");}catch(InterruptedException e){Thread.currentThread().interrupt();return new ExecutionResult(false,"Deployment interrupted.","Interrupted");}} }
